import {createPlaybackClock} from '/playback-clock.js';
import {initPlayerLyrics} from '/player-visuals.js';
import {artworkURL} from '/artwork.js';
export function initStudioPlayer({getTracks,toast,onChange,getLiked=()=>[],toggleLike=()=>{}}){
 const $=s=>document.querySelector(s),icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`,time=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
 const audio=document.createElement('audio');audio.id='studio-result-audio';audio.hidden=true;audio.preload='metadata';audio.volume=.55;document.body.append(audio);let track=null,ticket=0,volume=55;
 const lyrics=initPlayerLyrics({seek:seconds=>{audio.currentTime=seconds;update();}}),clock=createPlaybackClock(update);
 function update(){const duration=track?(Number.isFinite(audio.duration)?audio.duration:track.duration||0):0,position=track?audio.currentTime||0:0;$('#current-time').textContent=time(position);$('#duration').textContent=time(duration);$('#seek').value=duration?position/duration*100:0;$('#seek').style.setProperty('--playhead',$('#seek').value+'%');if(track)lyrics.update({...track,duration},!audio.paused,position);}
 function render(){const active=track&&!audio.paused;$('#play').innerHTML=icon(active?'pause':'play');$('#play').setAttribute('aria-label',active?'暂停':'播放');$('#play').disabled=!track;$('#seek').disabled=!track;$('#player-like').disabled=!track;$('#player-like').setAttribute('aria-pressed',String(track&&getLiked().includes(track.id)));if(track){$('#player-title').textContent=track.title;$('#player-artist').textContent=track.artist||'我的 Studio';$('#player-cover').src=artworkURL(track.art||'liquid-glass.png');}else{$('#player-title').textContent='选择作品开始播放';$('#player-artist').textContent='我的 Studio';$('#player-cover').src=artworkURL('liquid-glass.png');lyrics.update({id:'studio-idle',title:'选择作品开始播放',lyrics:'',type:'speech',duration:0},false,0);}clock.setPlaying(!!active);update();onChange?.(track?.id,!!active);}
 async function play(id,toggle=true){const next=getTracks().find(t=>t.id===id);if(!next?.audioURL){toast('这项内容还没有可播放的音频。');return;}if(track?.id===id&&!audio.paused&&toggle){audio.pause();return;}const request=++ticket;if(track?.id!==id){audio.pause();track=next;audio.src=next.audioURL;}if(audio.ended)audio.currentTime=0;try{await audio.play();if(request===ticket)render();}catch{if(request===ticket){render();toast('音频暂时无法播放，请重试。');}}}
 function step(direction){const tracks=getTracks().filter(t=>t.audioURL);if(!tracks.length)return;const index=tracks.findIndex(t=>t.id===track?.id);play(tracks[(index+direction+tracks.length)%tracks.length].id,false);}
 audio.addEventListener('loadedmetadata',render);audio.addEventListener('play',render);audio.addEventListener('pause',render);audio.addEventListener('ended',()=>{render();});audio.addEventListener('error',()=>{render();if(track)toast('音频读取失败，请稍后重试。');});
 $('#play').onclick=()=>track?audio.paused?play(track.id,false):audio.pause():null;$('#prev').onclick=()=>step(-1);$('#next').onclick=()=>step(1);$('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)/100*audio.duration;update();};$('#volume').oninput=e=>{audio.volume=Number(e.target.value)/100;$('#mute').setAttribute('aria-label',audio.volume?'静音':'取消静音');};$('#mute').onclick=()=>{const field=$('#volume');if(audio.volume){volume=Number(field.value);field.value=0;}else field.value=volume;field.dispatchEvent(new Event('input'));};$('#player-like').onclick=()=>{if(track){toggleLike(track.id);render();}};
 for(const id of ['shuffle','repeat']){$('#'+id).disabled=true;$('#'+id).title='Studio 播完当前作品后停止';}
 window.addEventListener('pagehide',event=>{audio.pause();ticket++;if(!event.persisted){clock.destroy();lyrics.destroy();}});render();
 return {play,pause:()=>audio.pause(),isPlaying:id=>track?.id===id&&!audio.paused,current:()=>track?.id,refresh:()=>{if(track){const next=getTracks().find(t=>t.id===track.id);if(next){track=next;render();}else{ticket++;audio.pause();track=null;audio.removeAttribute('src');render();}}},audio};
}
